## `app.js`

```javascript
/* ============================================
   GERENCIADOR DE TAREFAS - LÓGICA PRINCIPAL
   ============================================ */

// =====================================================
// 1. CONSTANTES E CONFIGURAÇÃO
// =====================================================

/** Chave usada no localStorage para persistência */
const STORAGE_KEY = 'task_manager_tasks';

/** Mapeamento de status para labels amigáveis em português */
const STATUS_LABELS = {
  pendente: 'Pendente',
  em_andamento: 'Em Andamento',
  concluído: 'Concluído'
};

/** Ordem das seções na exibição */
const SECTIONS_ORDER = ['pendente', 'em_andamento', 'concluído'];

// =====================================================
// 2. ESTADO DA APLICAÇÃO
// =====================================================

/** Array de tarefas carregado do localStorage ou vazio */
let tasks = loadTasks();

/** Filtro atualmente ativo ('todas', 'pendente', 'em_andamento', 'concluído') */
let currentFilter = 'todas';

// =====================================================
// 3. FUNÇÕES DE PERSISTÊNCIA (localStorage)
// =====================================================

/**
 * Carrega as tarefas do localStorage.
 * Se não houver dados salvos, retorna array vazio.
 * @returns {Array} Lista de tarefas
 */
function loadTasks() {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    console.error('Erro ao carregar tarefas do localStorage:', e);
    return [];
  }
}

/**
 * Salva o array de tarefas no localStorage.
 * @param {Array} tasksList - Lista de tarefas a ser salva
 */
function saveTasks(tasksList) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasksList));
  } catch (e) {
    console.error('Erro ao salvar tarefas no localStorage:', e);
  }
}

/**
 * Gera um ID único para cada tarefa usando timestamp + random.
 * @returns {string} ID único
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
}

// =====================================================
// 4. OPERAÇÕES CRUD (Criar, Ler, Atualizar, Deletar)
// =====================================================

/**
 * Cria uma nova tarefa e a adiciona ao estado.
 * @param {string} title - Título da tarefa
 * @param {string} description - Descrição da tarefa
 * @returns {Object} A tarefa criada
 */
function addTask(title, description) {
  const newTask = {
    id: generateId(),
    title: title.trim(),
    description: description.trim(),
    status: 'pendente', // Status inicial padrão
    createdAt: new Date().toISOString()
  };

  tasks.push(newTask);
  saveTasks(tasks);
  return newTask;
}

/**
 * Alterna o status da tarefa ciclando entre:
 * pendente → em_andamento → concluído → pendente
 * @param {string} id - ID da tarefa
 */
function toggleTask(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  // Ciclo de status: pendente → em_andamento → concluído → pendente
  const statusCycle = ['pendente', 'em_andamento', 'concluído'];
  const currentIndex = statusCycle.indexOf(task.status);
  task.status = statusCycle[(currentIndex + 1) % statusCycle.length];

  saveTasks(tasks);
}

/**
 * Exclui uma tarefa do estado.
 * @param {string} id - ID da tarefa a ser excluída
 * @returns {boolean} True se foi encontrada e removida
 */
function deleteTask(id) {
  const initialLength = tasks.length;
  tasks = tasks.filter(t => t.id !== id);
  const removed = tasks.length < initialLength;

  if (removed) {
    saveTasks(tasks);
  }
  return removed;
}

// =====================================================
// 5. FUNÇÕES DE FILTRAGEM
// =====================================================

/**
 * Filtra as tarefas com base no filtro ativo.
 * @param {string} filter - Filtro atual ('todas', 'pendente', etc.)
 * @returns {Array} Tarefas filtradas
 */
function getFilteredTasks(filter) {
  if (filter === 'todas') return tasks;
  return tasks.filter(t => t.status === filter);
}

/**
 * Agrupa as tarefas por status.
 * Útil para renderizar seções separadas.
 * @param {Array} tasksList - Lista de tarefas
 * @returns {Object} Objeto com arrays agrupados por status
 */
function groupTasksByStatus(tasksList) {
  const grouped = {};
  SECTIONS_ORDER.forEach(status => {
    grouped[status] = tasksList.filter(t => t.status === status);
  });
  return grouped;
}

// =====================================================
// 6. ATUALIZAÇÃO DA INTERFACE (Renderização)
// =====================================================

/**
 * Renderiza toda a interface de tarefas.
 * Chamada após qualquer operação que altere o estado.
 */
function renderTasks() {
  const container = document.getElementById('tasks-container');
  const emptyState = document.getElementById('empty-state');
  const filteredTasks = getFilteredTasks(currentFilter);

  // Limpa o container (mantendo o elemento de estado vazio)
  const sectionsHTML = buildSectionsHTML(filteredTasks);

  // Remove seções antigas, mantendo apenas o empty-state
  Array.from(container.querySelectorAll('.status-section')).forEach(el => el.remove());

  if (filteredTasks.length === 0) {
    // Mostra mensagem de lista vazia
    container.appendChild(emptyState);
    emptyState.style.display = 'block';
  } else {
    // Esconde a mensagem de lista vazia e insere as seções
    emptyState.style.display = 'none';

    // Insere as seções antes do elemento de estado vazio
    container.insertAdjacentHTML('beforeend', sectionsHTML);
  }

  // Atualiza os contadores nos botões de filtro
  updateFilterCounts();
}

/**
 * Constrói o HTML das seções de tarefas agrupadas por status.
 * @param {Array} filteredTasks - Tarefas filtradas
 * @returns {string} HTML das seções
 */
function buildSectionsHTML(filteredTasks) {
  const grouped = groupTasksByStatus(filteredTasks);

  return SECTIONS_ORDER.map(status => {
    const sectionTasks = grouped[status];

    // Não renderiza a seção se não houver tarefas (e o filtro for 'todas')
    if (sectionTasks.length === 0 && currentFilter === 'todas') return '';

    // Define o label e os ícones da seção
    const sectionLabel = STATUS_LABELS[status];
    const sectionEmoji = getSectionEmoji(status);

    // Constrói o HTML dos cards de tarefa
    const tasksHTML = sectionTasks.map(task => buildTaskCardHTML(task)).join('');

    return `
      <div class="status-section ${status}" data-status="${status}">
        <div class="status-section-header">
          <span>${sectionEmoji}</span>
          <span>${sectionLabel}</span>
          <span class="section-count">${sectionTasks.length}</span>
        </div>
        <div class="task-list">
          ${tasksHTML}
        </div>
      </div>
    `;
  }).join('');
}

/**
 * Constrói o HTML de um único card de tarefa.
 * @param {Object} task - Dados da tarefa
 * @returns {string} HTML do card
 */
function buildTaskCardHTML(task) {
  const label = STATUS_LABELS[task.status];
  // Trunca a descrição para evitar cards muito longos
  const description = task.description 
    ? `<p class="task-description">${escapeHTML(task.description)}</p>` 
    : '';

  return `
    <div class="task-card ${task.status}" data-id="${task.id}">
      <div class="task-checkbox"></div>
      <div class="task-content">
        <h3 class="task-title">${escapeHTML(task.title)}</h3>
        ${description}
      </div>
      <span class="task-status-badge ${task.status}">${label}</span>
      <button 
        class="btn-delete" 
        data-id="${task.id}" 
        title="Excluir tarefa"
        aria-label="Excluir tarefa: ${escapeHTML(task.title)}"
      >🗑️</button>
    </div>
  `;
}

/**
 * Retorna o emoji correspondente ao status para exibição nas seções.
 * @param {string} status - Status da tarefa
 * @returns {string} Emoji do status
 */
function getSectionEmoji(status) {
  const emojis = {
    pendente: '⏳',
    em_andamento: '🔄',
    concluído: '✅'
  };
  return emojis[status] || '📌';
}

/**
 * Atualiza os contadores de tarefas em cada botão de filtro.
 */
function updateFilterCounts() {
  // Conta quantas tarefas existem em cada status
  const counts = {
    todas: tasks.length,
    pendente: tasks.filter(t => t.status === 'pendente').length,
    em_andamento: tasks.filter(t => t.status === 'em_andamento').length,
    concluído: tasks.filter(t => t.status === 'concluído').length
  };

  // Atualiza cada badge no DOM
  Object.entries(counts).forEach(([status, count]) => {
    const badge = document.getElementById(`count-${status}`);
    if (badge) {
      badge.textContent = count;
    }
  });
}

/**
 * Escapa caracteres HTML para prevenir XSS.
 * @param {string} text - Texto a ser escapado
 * @returns {string} Texto com caracteres especiais escapados
 */
function escapeHTML(text) {
  const div = document.createElement('div');
  div.appendChild(document.createTextNode(text));
  return div.innerHTML;
}

// =====================================================
// 7. EVENT LISTENERS E INICIALIZAÇÃO
// =====================================================

/**
 * Configura todos os event listeners da aplicação.
 */
function setupEventListeners() {
  // --- Formulário de adição de tarefas ---
  const form = document.getElementById('task-form');
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const titleInput = document.getElementById('task-title');
    const descInput = document.getElementById('task-desc');

    const title = titleInput.value.trim();
    const description = descInput.value.trim();

    // Validação: título é obrigatório
    if (!title) {
      titleInput.focus();
      return;
    }

    // Cria a tarefa e limpa o formulário
    addTask(title, description);
    form.reset();
    titleInput.focus();

    // Re-renderiza a interface
    renderTasks();
  });

  // --- Delegação de eventos para filtros ---
  const filterSection = document.querySelector('.filter-buttons');
  filterSection.addEventListener('click', (e) => {
    const btn = e.target.closest('.filter-btn');
    if (!btn) return;

    const filter = btn.dataset.filter;
    if (!filter) return;

    // Atualiza o estado do filtro
    currentFilter = filter;

    // Atualiza visual dos botões (classe active)
    document.querySelectorAll('.filter-btn').forEach(b => {
      const isActive = b === btn;
      b.classList.toggle('active', isActive);
      b.setAttribute('aria-pressed', isActive);
    });

    renderTasks();
  });

  // --- Delegação de eventos para cards de tarefa ---
  const tasksContainer = document.getElementById('tasks-container');

  // Clique no card para alternar status da tarefa
  tasksContainer.addEventListener('click', (e) => {
    const taskCard = e.target.closest('.task-card');

    // Se clicou no botão de excluir, não alterna o status
    if (e.target.closest('.btn-delete')) return;
    if (!taskCard) return;

    const id = taskCard.dataset.id;
    toggleTask(id);
    renderTasks();
  });

  // Clique no botão de excluir com animação
  tasksContainer.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.btn-delete');
    if (!deleteBtn) return;

    const id = deleteBtn.dataset.id;
    const taskCard = deleteBtn.closest('.task-card');

    // Adiciona animação de remoção antes de deletar
    if (taskCard) {
      taskCard.classList.add('removing');

      // Aguarda a animação terminar antes de remover do DOM e do estado
      taskCard.addEventListener('animationend', () => {
        deleteTask(id);
        renderTasks();
      }, { once: true });
    } else {
      // Fallback se o card já não estiver no DOM
      deleteTask(id);
      renderTasks();
    }
  });
}

/**
 * Inicializa a aplicação quando o DOM estiver pronto.
 */
function init() {
  setupEventListeners();
  renderTasks();
}

// Inicia a aplicação assim que o HTML for processado
document.addEventListener('DOMContentLoaded', init);
```

